# Deduplicate by title while preserving order (in case any title repeats)
seen_titles = set()
unique_series = []
for row in SERIES:
    title = row[0]
    if title not in seen_titles:
        seen_titles.add(title)
        unique_series.append(row)

HEADERS = [
    "title", "genre", "cast", "director", "language",
    "platform", "release_year", "imdb_rating", "description",
]

OUTPUT_PATH = os.path.join(os.path.dirname(__file__), "data", "webseries.csv")


def main():
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    with open(OUTPUT_PATH, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(HEADERS)
        writer.writerows(unique_series)
    print(f"Wrote {len(unique_series)} unique series to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
